//Generic_GetLogAttributes
//Version 1
//Company: WCG
//Author: Roel Smeding

//-------
import groovy.xml.*;

class sqlAttributeLine
{
    String RunId
    String RunSubId
    String AttributeName
    String AttributeValue
}

def aggregatedXml = new XmlParser().parseText(request.getBody())
def sqlAttributeLines = []

def attributeList = aggregatedXml.'**'.findAll{ attribute -> attribute.name() == "Attribute"}
if (!attributeList.isEmpty()) {
    attributeList.eachWithIndex { attribute, index ->
        def line = new sqlAttributeLine(
                RunId: attribute.parent().parent().RunId.text(),
                RunSubId: attribute.RunSubId.text(),
                AttributeName: attribute.AttributeName.text().replaceAll(/(^\s*)|[\r\n\t]/, ""),
                AttributeValue: attribute.AttributeValue.text().replaceAll(/(^\s*)|[\r\n\t]/, "")
        )
        sqlAttributeLines.add(line);
    }
}
def String outputString = """INSERT INTO "DovetailLogAttributes" ("RunId","RunSubId","AttributeId","AttributeValue") \nVALUES \n"""

sqlAttributeLines.each { sqlAttributeLine line ->
    outputString += "('" + line.RunId + "','" + line.RunSubId + "','" + line.AttributeName + "','" + line.AttributeValue + "')," + "\n"
}

//Body or header?
//-------
request.setHeader("SQLcommand", outputString.take(outputString.length() -2))
result = outputString.take(outputString.length() -2)
